; page.asm -- chapter 30: printing, a second set, and a score
; generated by gen30.py
        INCLUDE "msx.inc"
        OUTPUT "page.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
score   EQU VARS                ; the score: three bytes of BCD, the highest first
count   EQU VARS + 3            ; the frames left
; A page printed from the ports, a name a character: at sets the address, print
; sends the characters. The title is in a second copy of the set, codes 160 to
; 255, white on black. The status line's score, BCD, is shown every frame.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $0000        ; the shapes: all paper first
        xor a
        ld e, 8
        call fill
        VRAM_WRITE $2000        ; the colours: codes 0 to 127 black on white ...
        ld a, $1F
        ld e, 4
        call fill
        ld a, $F1               ; ... 128 to 255 white on black
        ld e, 4
        call fill
c0:     VRAM_WRITE $0100        ; our set at 32 ...
        ld hl, font
        ld e, 3
        call send
        VRAM_WRITE $0500        ; ... and again at 160
        ld hl, font
        ld e, 3
        call send
c1:     VRAM_WRITE $1800        ; the names: spaces
        ld a, ' '
        ld e, 3
        call fill
p0:     ld hl, lines
        call page
p1:     ld hl, score            ; the score: 00 12 50
        ld (hl), $00
        inc hl
        ld (hl), $12
        inc hl
        ld (hl), $50
        call show
        VDP_REG 1, $C0          ; the display on
        in a, (VDP_CTRL)        ; F cleared: the first wait ends with a paper
        ld a, 48
        ld (count), a
loop:   call frame              ; the end of the paper
m0:     call show               ; the score, after the paper
m1:     call step               ; the next frame's points
s1:     ld hl, count
        dec (hl)
        jr nz, loop
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret

; at: the next characters go to row D, column E: name $1800 + 32 x D + E
at:     ld a, d
        rrca
        rrca
        rrca                    ; the row's bits 0-2 to 5-7, bits 3-4 to 0-1
        ld c, a
        and $E0                 ; 32 x the row, its low byte ...
        or e                    ; ... and the column
        out (VDP_CTRL), a
        ld a, c
        and $03                 ; 32 x the row, its high byte
        or $18 | $40            ; in the name table at $1800, for writing
        out (VDP_CTRL), a
        ret

; print: the characters from HL to the 0 after them, at the address set, in
; the set B says: 0 for the first, $80 for the second
print:  ld a, (hl)              ;  8
        or a                    ;  5
        ret z                   ;  6  the 0: HL is left on it
        or b                    ;  5
        out (VDP_DATA), a       ; 12
        inc hl                  ;  7
        jr print                ; 13: 56 T-states a character

; page: lines of text, each a row, a column, a set and its characters ended
; by 0; $FF after the last
page:   ld a, (hl)
        cp $FF
        ret z
        ld d, a                 ; the row
        inc hl
        ld e, (hl)              ; the column
        inc hl
        ld b, (hl)              ; the set
        inc hl
        call at
        call print
        inc hl                  ; past the 0
        jr page

; show: the score's six digits into the status line, after the paper: a
; digit is a nibble of BCD, and its name is '0' + the nibble
show:   VRAM_WRITE $1AE8        ; row 23, column 8
        ld hl, score
        ld b, 3                 ; three bytes, the highest first
.byte:  ld a, (hl)
        rrca
        rrca
        rrca
        rrca
        and $0F
        add a, '0'
        out (VDP_DATA), a       ; the high nibble's digit
        ld a, (hl)
        and $0F
        add a, '0'
        out (VDP_DATA), a       ; the low nibble's
        inc hl
        djnz .byte
        ret

; step: a leaf eaten, 75 points, added in BCD with DAA (chapter 9)
step:   ld hl, score + 2        ; the lowest two digits
        ld a, (hl)
        add a, $75
        daa
        ld (hl), a
        dec hl
        ld a, (hl)
        adc a, 0                ; the carry into the next two
        daa
        ld (hl), a
        dec hl
        ld a, (hl)
        adc a, 0
        daa
        ld (hl), a
        ret

; send: E blocks of 256 bytes from HL to the VDP with OTIR, after an address
; is set: the display is off (chapter 20)
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret

; fill: E blocks of 256 bytes of A to the VDP, after an address is set
fill:   ld b, 0
.out:   out (VDP_DATA), a
        djnz .out
        dec e
        jr nz, .out
        ret
lines:                          ; row, column, set, the text, 0
        db 1, 9, $80, " HOW TO PLAY ", 0
        db 4, 3, $00, "Guide the bug through the", 0
        db 5, 3, $00, "garden and eat every leaf", 0
        db 6, 3, $00, "before the sun goes down.", 0
        db 8, 3, $00, "Keep away from the birds:", 0
        db 9, 3, $00, "one touch, and the bug is", 0
        db 10, 3, $00, "gone.", 0
        db 12, 5, $00, "Cursor keys    move", 0
        db 13, 5, $00, "Space          jump", 0
        db 14, 5, $00, "Escape         pause", 0
        db 16, 3, $00, "A leaf is worth 75 points.", 0
        db 23, 2, $00, "SCORE", 0
        db $FF
        INCLUDE "font.inc"
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
